    return "@extends('layouts.app')\n\n@section('title', '" + label(plural(module.entity)) + "')\n\n@section('content')\n<div class=\"container py-4\">\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n        <h1 class=\"h3\">" + label(plural(module.entity)) + "</h1>\n        @can('create', App\\Models\\" + entity + "::class)\n            <a class=\"btn btn-primary\" href=\"{{ route('" + module.id + ".create') }}\">New " + label(module.entity) + "</a>\n        @endcan\n    </div>\n\n    <form method=\"GET\" class=\"mb-3\">\n        <label class=\"visually-hidden\" for=\"q\">Search</label>\n        <input id=\"q\" name=\"q\" value=\"{{ request('q') }}\" class=\"form-control\" placeholder=\"Search\">\n    </form>\n\n    <div class=\"table-responsive\">\n        <table class=\"table align-middle\">\n            <thead><tr><th>ID</th><th>Details</th><th>Status</th><th></th></tr></thead>\n            <tbody>\n            @forelse ($" + many + " as $" + variable + ")\n                <tr>\n                    <td>{{ $" + variable + "->id }}</td>\n                    <td><a href=\"{{ route('" + module.id + ".show', $" + variable + ") }}\">{{ $" + variable + "->" + (parseColumns(module).some(column => column.name === 'name') ? 'name' : parseColumns(module).some(column => column.name === 'title') ? 'title' : 'id') + " }}</a></td>\n                    <td>{{ $" + variable + "->status ?? '—' }}</td>\n                    <td class=\"text-end\">@can('update', $" + variable + ") <a href=\"{{ route('" + module.id + ".edit', $" + variable + ") }}\">Edit</a> @endcan</td>\n                </tr>\n            @empty\n                <tr><td colspan=\"4\" class=\"text-center text-muted py-4\">No records yet.</td></tr>\n            @endforelse\n            </tbody>\n        </table>\n    </div>\n    {{ $" + many + "->links() }}\n</div>\n@endsection";
