    if (column.type === 'text') return "        <textarea name=\"" + name + "\" id=\"" + name + "\" class=\"form-control\" rows=\"4\"{{ " + (column.nullable ? '' : ' required') + " }}>{{ old('" + name + "', $record->" + name + " ?? '') }}</textarea>" + error;
