    if (column.type === 'integer' || column.type === 'foreignId') return "        <input type=\"number\" name=\"" + name + "\" id=\"" + name + "\" class=\"form-control\" value=\"{{ old('" + name + "', $record->" + name + " ?? '') }}\"{{ " + required + " }}>" + error;
