    return "        <input type=\"" + (name === 'email' ? 'email' : 'text') + "\" name=\"" + name + "\" id=\"" + name + "\" class=\"form-control\" value=\"{{ old('" + name + "', $record->" + name + " ?? '') }}\"{{ " + required + " }}>" + error;
